import { app, BrowserWindow, ipcMain, shell } from 'electron';
import fs from 'fs';
import path from 'path';
import { DB } from "./database/database";
import { setUpHandlers } from "./requestHandler";
import { startMail } from "./mail/ipc";
import { createImageTable, registerImageScheme, setUpImages } from "./images";
import { setUpSpelling } from "./spelling";
import { setUpPdf } from "./pdf";
// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Webpack
// plugin that tells the Electron app where to look for the Webpack-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

// Handle creating/removing shortcuts on Windows when installing/uninstalling.
if (require('electron-squirrel-startup')) {
    app.quit();
}

// ── Single instance + "open X" commands ──────────────────────────────────────
// `MyNotion --open=calendar` / `--open=note:12` / `--open=home` shows that page. Aria uses this.
// Starting MyNotion while it's already running focuses the existing window instead of opening a
// second one (two copies would both write the same database).
const openArg = (argv: string[]): string | null => {
    const a = argv.find(x => x.startsWith('--open='));
    return a ? a.slice('--open='.length) : null;
};
let pendingOpen: string | null = openArg(process.argv);

// pictures in notes are loaded from mynotion-image:// links (see images.ts); this has to happen before 'ready'
registerImageScheme();
let mainWindow: BrowserWindow | null = null;

const gotLock = app.requestSingleInstanceLock();
if (!gotLock) {
    // Another MyNotion already got our arguments via 'second-instance'. Exit right now:
    // app.quit() only schedules quitting, so startup (DB, window) would still run and crash.
    app.exit(0);
} else {
    app.on('second-instance', (_event, argv) => {
        if (mainWindow) {
            if (mainWindow.isMinimized()) mainWindow.restore();
            mainWindow.show();
            mainWindow.focus();
            const target = openArg(argv);
            if (target) mainWindow.webContents.send('open-target', target);
        }
    });
}

const createWindow = (): void => {
    // Create the browser window.
    mainWindow = new BrowserWindow({
        height: 800,
        width: 800,
        title: 'MyNotion',
        // the green notebook in the taskbar (packaged: next to the app's other files)
        icon: app.isPackaged ? path.join(process.resourcesPath, 'icon.png') : path.join(__dirname, '../../assets/icon.png'),
        show: false,          // shown maximized once ready, so it doesn't flash at 800x800 first
        //frame: false,
        webPreferences: {
            preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
        },


    });

    // Open filling the screen (title bar and taskbar stay; F11 for real fullscreen).
    mainWindow.once('ready-to-show', () => {
        mainWindow?.maximize();
        mainWindow?.show();
    });

    // German + English spell-check, and the right-click menu (suggestions, cut / copy / paste)
    setUpSpelling(mainWindow);

    // Links in notes open in the normal browser, never inside the app window.
    mainWindow.webContents.setWindowOpenHandler(({ url }) => {
        if (/^(https?|mailto):/i.test(url)) shell.openExternal(url);
        return { action: 'deny' };
    });

    // In development the Angular app is served on its own dev server.
    // In a packaged build its dist is copied into the app resources, so load
    // it from disk instead.
    if (app.isPackaged) {
        mainWindow.loadFile(path.join(process.resourcesPath, 'browser', 'index.html'));
    } else {
        mainWindow.loadURL('http://localhost:4200');
    }
    // Open the DevTools.
    mainWindow.setAutoHideMenuBar(false);
};

// Other programs (e.g. the Aria assistant) write to the same SQLite file. Watch it and
// tell the renderer, so new notes and events show up without restarting the app.
const watchDatabase = (): void => {
    const dbFile = DB.filePath;
    const dir = path.dirname(dbFile);
    const base = path.basename(dbFile);
    let timer: NodeJS.Timeout | null = null;
    try {
        fs.watch(dir, (_event, filename) => {
            // noted.db, noted.db-journal, noted.db-wal all mean "data changed"
            if (!filename || !filename.toString().startsWith(base)) return;
            if (timer) clearTimeout(timer);
            timer = setTimeout(() => {
                for (const win of BrowserWindow.getAllWindows()) {
                    win.webContents.send('db-changed');
                }
            }, 400);
        });
    } catch (err) {
        console.error('Could not watch the database for outside changes:', err);
    }
};

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
// Some APIs can only be used after this event occurs.
app.whenReady().then(async () => {
    if (!gotLock) return;   // this copy is exiting; the running one handles the request
    await DB.getConnection();
    await DB.initializeTables();
    await createImageTable();
    setUpHandlers();
    setUpImages();
    setUpPdf();
    startMail();
    // the page asks once it has loaded, so an --open from startup isn't lost
    ipcMain.handle('take-open-target', () => {
        const t = pendingOpen;
        pendingOpen = null;
        return t;
    });
    createWindow();
    watchDatabase();
    // a backup per day: now, and hourly checks in case the app stays open past midnight
    DB.backupDaily();
    setInterval(() => DB.backupDaily(), 60 * 60 * 1000);
})

// Quit when all windows are closed, except on macOS. There, it's common
// for applications and their menu bar to stay active until the user quits
// explicitly with Cmd + Q.
app.on('window-all-closed', () => {
    if (process.platform !== 'darwin') {
        app.quit();
    }
});

app.on('activate', () => {
    // On OS X it's common to re-create a window in the app when the
    // dock icon is clicked and there are no other windows open.
    if (BrowserWindow.getAllWindows().length === 0) {
        createWindow();
    }
});

